    (role(game).privateState as Record<string, unknown>).awakened_hidden_wolf = structuredClone(
      state(game),
    );
    if (other)
      ctx.state.poisonClaims!.push({
        source: captureNightLife(game.world, 4)!,
        target: captureNightLife(game.world, 6)!,
      });
