          name: "inspect_night_identity",
          args: { target_id: r.actorId === pure ? wolf : pure, abstain: false },
        };
      },
    },
    makeRequest: (actorId, allowedTools, extras) => ({
      actorId,
      allowedTools,
      phase: Phase.Night,
      context: {
        day,
        ...extras,
        visible_events: [],
        turn_constraints: {
