      requests.create({
        summary: "Offline stage fixture",
        requiresAction: true,
        actorId,
        phase: Phase.Night,
        allowedTools,
        stage: extra.stage,
        context: extra,
      }),
    ensureMarks: (id) => {
      let marks = game.world.getComponent(id, COMPONENT.StatusMarks);
      if (!marks) {
        marks = new StatusMarksComponent();
        game.world.addComponent(id, COMPONENT.StatusMarks, marks);
      }
      return marks;
    },
    state: {
      wolfChatOrder: [],
