for (const change of [
  "source",
  "source_role",
  "expiry",
  "starts",
  "max_uses",
  "disclosure",
] as const) {
  for (const boundary of ["request", "reply", "validation"] as const) {
    test(`${change}/${boundary}: potion metadata belongs to the captured ability scope`, async () => {
      const game = fixture(),
        events: GameEvent[] = [];
      const ability = findNightAbility(role(game, 2), "potion")!;
      const oldState = ability.state;
      const mutate = () => {
        switch (change) {
          case "source":
            (
              ability as {
                source: import("@ai-werewolf-arena/game-contract").AbilitySource;
              }
            ).source = { kind: "native", role: Role.Witch };
            break;
          case "source_role":
            if (ability.source.kind === "native")
              (ability.source as { role: Role }).role = Role.Villager;
            break;
          case "expiry":
            (ability as { expiresAfterDay: number | undefined }).expiresAfterDay = 10;
            break;
          case "starts":
            (ability as { startsOnDay: number }).startsOnDay = 0;
            break;
          case "max_uses":
            (ability as { maxUses: number | null }).maxUses = 2;
            break;
          case "disclosure":
            (ability as { sourceDisclosed: boolean }).sourceDisclosed = !ability.sourceDisclosed;
            break;
        }
      };
      let calls = 0;
      const ctx = context(game, events, async () => {
        calls++;
        if (boundary === "reply") mutate();
        return { name: "use_potion", args: { target_id: 5, potion_type: PotionType.Poison } };
      });
      if (boundary === "request") {
        const makeRequest = ctx.makeRequest;
        ctx.makeRequest = (...args) => {
          const request = makeRequest(...args);
          mutate();
          return request;
        };
      }
      if (boundary === "validation") {
        const validate = ctx.toolGateway.validateAndSanitize.bind(ctx.toolGateway);
        ctx.toolGateway.validateAndSanitize = (...args) => {
          const result = validate(...args);
          mutate();
          return result;
        };
      }
      await stage.execute(ctx);
      expect(calls).toBe(boundary === "request" ? 0 : 1);
      expect(oldState.poison).toBe(1);
      expect(ability.uses).toBe(0);
      expect(ability.lastUsedDay).toBeNull();
      expect(ctx.state.poisonClaims).toEqual([]);
      expect(events).toEqual([]);
      expect(
        game.world
          .getComponent(5, COMPONENT.StatusMarks)
          ?.has(StatusMark.PoisonMark) ?? false,
      ).toBe(false);
    });
  }
}

