        maxUses: 1,
      },
      events,
    );
  game.world
    .getComponent(6, COMPONENT.StatusMarks)!
    .add(StatusMark.WolfKillMark);
  const ctx = context(game, 1, events, async () => ({
    name: "use_potion",
